package httpapi

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"
	"time"
)

// openapi.yaml declares {assetId} as `format: uuid` and promises 404 as the only
// failure for GET, PATCH, DELETE and restore on /api/v1/assets/{assetId}, while
// the history and relations collections promise 200 and nothing else. The five
// handlers put chi.URLParam(request, "assetID") straight into `WHERE id = $1`.
// assets.id, asset_changes.asset_id and asset_relations.source/target_asset_id
// are UUID columns on PostgreSQL and TEXT on the SQLite fallback, so the same
// request diverged by dialect: a spelling PostgreSQL's uuid input rejects failed
// the query with SQLSTATE 22P02 and surfaced as a 500 openapi never declares,
// and an upper-case id — the declared form — was folded by PostgreSQL into a hit
// where SQLite's comparison matched nothing and answered 404.
//
// These tests run through the real router against the real Runtime, and look at
// the rows the handlers write rather than at the response code alone.

// assetIDResponse calls one of the five routes for the given raw path parameter
// and reports the status with the error code, if any.
func assetIDResponse(
	t *testing.T, server *Server, cookie *http.Cookie, csrf, method, path string,
	body any,
) (int, string, string) {
	t.Helper()
	response := performAuthenticatedJSON(t, server, method, path, body, cookie, csrf)
	var payload struct {
		Error struct {
			Code string `json:"code"`
		} `json:"error"`
	}
	_ = json.Unmarshal(response.Body.Bytes(), &payload)
	return response.Code, payload.Error.Code, response.Body.String()
}

// assetIDSpellings are the path parameters uuid.Parse accepts, or does not,
// without being the 36-character hyphenated form openapi declares. The first is
// not a UUID in any reading; the rest are alternative spellings of an id that
// does name an asset, and are the ones whose handling diverged by dialect.
func assetIDSpellings(canonical string) map[string]string {
	return map[string]string{
		"not a uuid at all": "not-a-uuid",
		"urn prefixed":      "urn:uuid:" + canonical,
		"brace wrapped":     "{" + canonical + "}",
		"unhyphenated":      strings.ReplaceAll(canonical, "-", ""),
	}
}

// assetRowState reads back the two columns a delete and a restore move, so a
// handler that answered 404 after having already written is still caught.
func assetRowState(t *testing.T, server *Server, id string) (string, bool) {
	t.Helper()
	var status string
	var deletedAt any
	if err := server.database.DB().QueryRow(
		`SELECT status, deleted_at FROM assets WHERE id=$1`, id,
	).Scan(&status, &deletedAt); err != nil {
		t.Fatalf("read asset %s: %v", id, err)
	}
	return status, deletedAt != nil
}

// A path parameter that is not the declared canonical UUID has to be refused
// before any query runs, with the 404 openapi declares, on both dialects.
func TestAssetRoutesAnswer404ForNonCanonicalAssetID(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	assetID := insertSoftwareTestAsset(t, server, "param-shape",
		"param-shape", "host", `{}`, 1, now)

	routes := []struct {
		name   string
		method string
		suffix string
		body   any
	}{
		{"get", http.MethodGet, "", nil},
		{"patch", http.MethodPatch, "", map[string]any{"name": "renamed by a bad id"}},
		{"delete", http.MethodDelete, "", nil},
		{"restore", http.MethodPost, "/restore", nil},
	}
	for _, route := range routes {
		for label, spelling := range assetIDSpellings(assetID) {
			status, code, body := assetIDResponse(t, server, cookie, csrf,
				route.method, "/api/v1/assets/"+spelling+route.suffix, route.body)
			if status != http.StatusNotFound || code != "ASSET_NOT_FOUND" {
				t.Errorf("%s with a %s asset id (%q) = %d %q, want 404 ASSET_NOT_FOUND: %s",
					route.name, label, spelling, status, code, body)
			}
		}
	}
	// None of those requests may have touched the asset they spell loosely.
	if status, deleted := assetRowState(t, server, assetID); status != "active" || deleted {
		t.Errorf("asset after the refused requests = status %q deleted %v, want active false",
			status, deleted)
	}
	if changes := countRows(t, server,
		`SELECT COUNT(*) FROM asset_changes WHERE asset_id=$1`, assetID,
	); changes != 0 {
		t.Errorf("asset_changes rows written by the refused requests = %d, want 0", changes)
	}
}

// history and relations declare 200 and no 404 at all, so a path parameter they
// cannot look up has to answer an empty collection rather than a 500 on
// PostgreSQL and an empty one on the fallback.
func TestAssetCollectionsAnswerEmptyForNonCanonicalAssetID(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	assetID := insertSoftwareTestAsset(t, server, "collection-shape",
		"collection-shape", "host", `{}`, 1, now)
	peerID := insertSoftwareTestAsset(t, server, "collection-peer",
		"collection-peer", "software_product", `{}`, 1, now)
	insertRunsOn(t, server, peerID, assetID)

	for _, suffix := range []string{"/history", "/relations"} {
		for label, spelling := range assetIDSpellings(assetID) {
			response := performAuthenticatedJSON(t, server, http.MethodGet,
				"/api/v1/assets/"+spelling+suffix, nil, cookie, csrf)
			if response.Code != http.StatusOK {
				t.Errorf("%s with a %s asset id (%q) = %d, want 200: %s",
					suffix, label, spelling, response.Code, response.Body.String())
				continue
			}
			var payload struct {
				Items []map[string]any `json:"items"`
			}
			if err := json.Unmarshal(response.Body.Bytes(), &payload); err != nil {
				t.Errorf("%s with a %s asset id: decode %s: %v",
					suffix, label, response.Body.String(), err)
				continue
			}
			if len(payload.Items) != 0 {
				t.Errorf("%s with a %s asset id returned %d items, want 0",
					suffix, label, len(payload.Items))
			}
		}
	}
}

// The upper-case 36-character form is the spelling openapi declares, and
// PostgreSQL folded it into a hit where the fallback's TEXT comparison did not.
// Every route has to act on the asset itself, which is checked here on the rows
// the handlers write rather than on the response codes.
func TestAssetRoutesAcceptUpperCaseAssetID(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	assetID := insertSoftwareTestAsset(t, server, "upper-case-shape",
		"upper-case-shape", "host", `{}`, 1, now)
	peerID := insertSoftwareTestAsset(t, server, "upper-case-peer",
		"upper-case-peer", "software_product", `{}`, 1, now)
	insertRunsOn(t, server, peerID, assetID)
	shouting := strings.ToUpper(assetID)
	base := "/api/v1/assets/" + shouting

	// GET has to find it and report the canonical id back.
	getStatus, getCode, getBody := assetIDResponse(t, server, cookie, csrf,
		http.MethodGet, base, nil)
	if getStatus != http.StatusOK {
		t.Fatalf("get with an upper-case id = %d %q, want 200: %s",
			getStatus, getCode, getBody)
	}
	var read struct {
		Asset struct {
			ID   string `json:"id"`
			Name string `json:"name"`
		} `json:"asset"`
	}
	if err := json.Unmarshal([]byte(getBody), &read); err != nil {
		t.Fatalf("decode %s: %v", getBody, err)
	}
	if read.Asset.ID != assetID {
		t.Errorf("get returned id %q, want the canonical %q", read.Asset.ID, assetID)
	}

	// PATCH has to land on the stored row, not just answer 200.
	patchStatus, patchCode, patchBody := assetIDResponse(t, server, cookie, csrf,
		http.MethodPatch, base, map[string]any{
			"name": "renamed through a shouting id", "reason": "same asset",
		})
	if patchStatus != http.StatusOK {
		t.Fatalf("patch with an upper-case id = %d %q, want 200: %s",
			patchStatus, patchCode, patchBody)
	}
	var stored string
	if err := server.database.DB().QueryRow(
		`SELECT name FROM assets WHERE id=$1`, assetID,
	).Scan(&stored); err != nil {
		t.Fatalf("read the patched name: %v", err)
	}
	if stored != "renamed through a shouting id" {
		t.Errorf("assets.name = %q, want the patched name", stored)
	}

	// DELETE and restore move deleted_at and status on that same row.
	if status, code, body := assetIDResponse(t, server, cookie, csrf,
		http.MethodDelete, base, nil); status != http.StatusOK {
		t.Fatalf("delete with an upper-case id = %d %q, want 200: %s", status, code, body)
	}
	if status, deleted := assetRowState(t, server, assetID); status != "deleted" || !deleted {
		t.Errorf("asset after the delete = status %q deleted %v, want deleted true",
			status, deleted)
	}
	if status, code, body := assetIDResponse(t, server, cookie, csrf,
		http.MethodPost, base+"/restore", nil); status != http.StatusOK {
		t.Fatalf("restore with an upper-case id = %d %q, want 200: %s", status, code, body)
	}
	if status, deleted := assetRowState(t, server, assetID); status != "active" || deleted {
		t.Errorf("asset after the restore = status %q deleted %v, want active false",
			status, deleted)
	}

	// The change rows have to be attached to the canonical id, because that is
	// what every later lookup spells.
	for changeType, want := range map[string]int{"updated": 1, "deleted": 1, "restored": 1} {
		if got := countRows(t, server,
			`SELECT COUNT(*) FROM asset_changes WHERE asset_id=$1 AND change_type=$2`,
			assetID, changeType,
		); got != want {
			t.Errorf("asset_changes %q rows for the canonical id = %d, want %d",
				changeType, got, want)
		}
	}

	// And the two collections have to report that history and the relation.
	historyResponse := performAuthenticatedJSON(t, server, http.MethodGet,
		base+"/history", nil, cookie, csrf)
	var history struct {
		Items []map[string]any `json:"items"`
	}
	if err := json.Unmarshal(historyResponse.Body.Bytes(), &history); err != nil {
		t.Fatalf("decode history %s: %v", historyResponse.Body.String(), err)
	}
	if historyResponse.Code != http.StatusOK || len(history.Items) != 3 {
		t.Errorf("history with an upper-case id = %d with %d items, want 200 with 3",
			historyResponse.Code, len(history.Items))
	}
	relationsResponse := performAuthenticatedJSON(t, server, http.MethodGet,
		base+"/relations", nil, cookie, csrf)
	var relations struct {
		Items []map[string]any `json:"items"`
	}
	if err := json.Unmarshal(relationsResponse.Body.Bytes(), &relations); err != nil {
		t.Fatalf("decode relations %s: %v", relationsResponse.Body.String(), err)
	}
	if relationsResponse.Code != http.StatusOK || len(relations.Items) != 1 {
		t.Errorf("relations with an upper-case id = %d with %d items, want 200 with 1",
			relationsResponse.Code, len(relations.Items))
	}
}
package httpapi

import (
	"encoding/json"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/google/uuid"
)

// openapi.yaml promises `400 Primary or secondary assets missing` for
// POST /api/v1/assets/merge, but the handler never looked the ids up. A
// secondary that is not an asset updated no rows and still answered 200 while
// writing a "merged" asset_changes row and a successful audit entry; a primary
// that is not an asset only surfaced as the asset_changes foreign key failing,
// i.e. a 500. Both are checked here through the real router.

// mergeAssetsResponse posts to the production merge route.
func mergeAssetsResponse(
	t *testing.T, server *Server, cookie *http.Cookie, csrf, primaryID string,
	secondaryIDs ...string,
) (int, string) {
	t.Helper()
	response := performAuthenticatedJSON(t, server, http.MethodPost,
		"/api/v1/assets/merge",
		map[string]any{
			"primary_id": primaryID, "secondary_ids": secondaryIDs,
			"reason": "duplicate host",
		}, cookie, csrf)
	var payload struct {
		Error struct {
			Code string `json:"code"`
		} `json:"error"`
	}
	_ = json.Unmarshal(response.Body.Bytes(), &payload)
	return response.Code, payload.Error.Code
}

func countRows(t *testing.T, server *Server, query string, args ...any) int {
	t.Helper()
	var count int
	if err := server.database.DB().QueryRow(query, args...).Scan(&count); err != nil {
		t.Fatalf("count %q: %v", query, err)
	}
	return count
}

// assertMergeWroteNothing checks the two tables a merge writes to, because a
// response code alone would not catch a rolled-back handler that had already
// recorded a successful merge.
func assertMergeWroteNothing(t *testing.T, server *Server) {
	t.Helper()
	if changes := countRows(t, server,
		`SELECT COUNT(*) FROM asset_changes WHERE change_type='merged'`,
	); changes != 0 {
		t.Fatalf("asset_changes 'merged' rows = %d, want 0", changes)
	}
	if entries := countRows(t, server,
		`SELECT COUNT(*) FROM audit_logs WHERE action='asset.merge'`,
	); entries != 0 {
		t.Fatalf("audit_logs 'asset.merge' rows = %d, want 0", entries)
	}
}

func assetStatus(t *testing.T, server *Server, assetID string) string {
	t.Helper()
	var status string
	if err := server.database.DB().QueryRow(
		`SELECT status FROM assets WHERE id=$1`, assetID,
	).Scan(&status); err != nil {
		t.Fatalf("read status of %s: %v", assetID, err)
	}
	return status
}

func TestMergeAssetsRejectsPrimaryThatIsNotAnAsset(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	secondaryID := insertSoftwareTestAsset(t, server, "orphan-secondary",
		"orphan-secondary", "host", `{}`, 1, now)

	status, code := mergeAssetsResponse(t, server, cookie, csrf, uuid.NewString(),
		secondaryID)
	if status != http.StatusBadRequest || code != "INVALID_MERGE" {
		t.Fatalf("merge into a missing primary = %d %q, want 400 INVALID_MERGE",
			status, code)
	}
	if got := assetStatus(t, server, secondaryID); got != "active" {
		t.Fatalf("secondary status = %q, want it untouched (active)", got)
	}
	assertMergeWroteNothing(t, server)
}

// The whole request rolls back: a secondary that exists alongside one that does
// not stays unmerged, rather than half the request succeeding.
func TestMergeAssetsRejectsMissingSecondaryWithoutMergingTheOthers(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	primaryID := insertSoftwareTestAsset(t, server, "keep-primary", "keep-primary",
		"host", `{}`, 1, now)
	realSecondaryID := insertSoftwareTestAsset(t, server, "keep-secondary",
		"keep-secondary", "host", `{}`, 1, now.Add(-time.Minute))

	status, code := mergeAssetsResponse(t, server, cookie, csrf, primaryID,
		realSecondaryID, uuid.NewString())
	if status != http.StatusBadRequest || code != "INVALID_MERGE" {
		t.Fatalf("merge with a missing secondary = %d %q, want 400 INVALID_MERGE",
			status, code)
	}
	if got := assetStatus(t, server, realSecondaryID); got != "active" {
		t.Fatalf("the existing secondary was merged anyway: status = %q", got)
	}
	if got := assetStatus(t, server, primaryID); got != "active" {
		t.Fatalf("primary status = %q, want active", got)
	}
	assertMergeWroteNothing(t, server)
}

// assets.id is a UUID column on PostgreSQL and TEXT on the SQLite fallback, so
// an id that is not a UUID would make the lookup itself fail on one dialect
// only. Both must answer the same code for the same input.
func TestMergeAssetsRejectsIdsThatAreNotUUIDs(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	primaryID := insertSoftwareTestAsset(t, server, "shape-primary",
		"shape-primary", "host", `{}`, 1, now)

	status, code := mergeAssetsResponse(t, server, cookie, csrf, primaryID,
		"not-a-uuid")
	if status != http.StatusBadRequest || code != "INVALID_MERGE" {
		t.Fatalf("merge with a malformed secondary id = %d %q, want 400 INVALID_MERGE",
			status, code)
	}
	assertMergeWroteNothing(t, server)
}

// primary_id reaches assets.id and asset_sources.asset_id, UUID columns on
// PostgreSQL and TEXT on the SQLite fallback. Every spelling uuid.Parse accepts
// but openapi does not declare (`format: uuid`) has to be refused before any
// query runs: PostgreSQL rejects the urn: one with SQLSTATE 22P02, surfacing as
// a 500 openapi never promises, and silently folds the brace and unhyphenated
// ones so the merge went through on rows the fallback matched not at all.
// nonCanonicalSpellings is shared with the split tests in
// asset_split_validation_test.go.
func TestMergeAssetsRejectsNonCanonicalPrimaryID(t *testing.T) {
	for name, rewrite := range nonCanonicalSpellings {
		t.Run(name, func(t *testing.T) {
			runtime := newRuntime(t)
			server := testServer(t, runtime)
			cookie, csrf := authenticateInitialAdmin(t, server, runtime)
			now := time.Now().UTC()
			primaryID := insertSoftwareTestAsset(t, server, "shape-merge-primary",
				"shape-merge-primary", "host", `{}`, 1, now)
			secondaryID := insertSoftwareTestAsset(t, server, "shape-merge-secondary",
				"shape-merge-secondary", "host", `{}`, 1, now.Add(-time.Minute))

			// Rewriting an id that really is an asset is what makes this bite: on
			// PostgreSQL the brace and unhyphenated forms matched the real row.
			spelling := rewrite(primaryID)
			status, code := mergeAssetsResponse(t, server, cookie, csrf, spelling,
				secondaryID)
			if status != http.StatusBadRequest || code != "INVALID_MERGE" {
				t.Fatalf("merge into primary %q = %d %q, want 400 INVALID_MERGE",
					spelling, status, code)
			}
			if got := assetStatus(t, server, secondaryID); got != "active" {
				t.Fatalf("secondary status = %q, want it untouched (active)", got)
			}
			assertMergeWroteNothing(t, server)
		})
	}
}

// Same for every secondary_ids element: it names the asset whose sources move
// and whose status flips, so a folded spelling carried the merge out on
// PostgreSQL alone.
func TestMergeAssetsRejectsNonCanonicalSecondaryIDs(t *testing.T) {
	for name, rewrite := range nonCanonicalSpellings {
		t.Run(name, func(t *testing.T) {
			runtime := newRuntime(t)
			server := testServer(t, runtime)
			cookie, csrf := authenticateInitialAdmin(t, server, runtime)
			now := time.Now().UTC()
			primaryID := insertSoftwareTestAsset(t, server, "shape-sec-primary",
				"shape-sec-primary", "host", `{}`, 1, now)
			goodSecondaryID := insertSoftwareTestAsset(t, server, "shape-sec-good",
				"shape-sec-good", "host", `{}`, 1, now.Add(-time.Minute))
			mergeableID := insertSoftwareTestAsset(t, server, "shape-sec-mergeable",
				"shape-sec-mergeable", "host", `{}`, 1, now.Add(-2*time.Minute))

			spelling := rewrite(mergeableID)
			status, code := mergeAssetsResponse(t, server, cookie, csrf, primaryID,
				goodSecondaryID, spelling)
			if status != http.StatusBadRequest || code != "INVALID_MERGE" {
				t.Fatalf("merge with secondary %q = %d %q, want 400 INVALID_MERGE",
					spelling, status, code)
			}
			if got := assetStatus(t, server, goodSecondaryID); got != "active" {
				t.Fatalf("the well-formed secondary was merged anyway: status = %q", got)
			}
			if got := assetStatus(t, server, mergeableID); got != "active" {
				t.Fatalf("the asset named by %q was merged: status = %q", spelling, got)
			}
			assertMergeWroteNothing(t, server)
		})
	}
}

// Upper-case hex is the one spelling openapi declares, just not folded:
// PostgreSQL's uuid input folds it and the fallback's TEXT comparison does not.
// The handler has to fold it itself so the merge happens on both dialects, and
// so asset_changes.after_json records the canonical secondary - the MCP
// merged_into lookup (mcp.go) matches that list by exact text on both engines,
// so an upper-case id stored there merges the asset without ever pointing a
// client at its primary.
func TestMergeAssetsFoldsUpperCaseIDsToCanonicalForm(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	primaryID := insertSoftwareTestAsset(t, server, "upper-merge-primary",
		"upper-merge-primary", "host", `{}`, 1, now)
	secondaryID := insertSoftwareTestAsset(t, server, "upper-merge-secondary",
		"upper-merge-secondary", "host", `{}`, 1, now.Add(-time.Minute))
	movedSourceID := insertTestAssetSource(t, server, secondaryID, "upper-merge-source")

	upperSecondary := strings.ToUpper(secondaryID)
	status, code := mergeAssetsResponse(t, server, cookie, csrf,
		strings.ToUpper(primaryID), upperSecondary)
	if status != http.StatusOK {
		t.Fatalf("merge with upper-case ids = %d %q, want 200", status, code)
	}
	if got := assetStatus(t, server, secondaryID); got != "merged" {
		t.Fatalf("secondary status = %q, want merged", got)
	}
	if got := assetStatus(t, server, primaryID); got != "active" {
		t.Fatalf("primary status = %q, want active", got)
	}
	if got := sourceOwner(t, server, movedSourceID); got != primaryID {
		t.Fatalf("source owner = %q, want the canonical primary %q", got, primaryID)
	}
	if changes := countRows(t, server,
		`SELECT COUNT(*) FROM asset_changes WHERE change_type='merged' AND asset_id=$1`,
		primaryID,
	); changes != 1 {
		t.Fatalf("asset_changes 'merged' rows for the canonical primary = %d, want 1",
			changes)
	}
	if entries := countRows(t, server,
		`SELECT COUNT(*) FROM audit_logs WHERE action='asset.merge' AND resource_id=$1`,
		primaryID,
	); entries != 1 {
		t.Fatalf("audit_logs 'asset.merge' rows for the canonical primary = %d, want 1",
			entries)
	}
	var afterJSON string
	if err := server.database.DB().QueryRow(
		`SELECT after_json FROM asset_changes WHERE change_type='merged' AND asset_id=$1`,
		primaryID,
	).Scan(&afterJSON); err != nil {
		t.Fatalf("read the recorded merge of %s: %v", primaryID, err)
	}
	if !strings.Contains(afterJSON, secondaryID) || strings.Contains(afterJSON, upperSecondary) {
		t.Fatalf("asset_changes.after_json = %s, want the canonical %q and not %q",
			afterJSON, secondaryID, upperSecondary)
	}
}

// The point of recording the canonical secondary: MCP asset_get has to be able
// to tell a client holding the merged id where its asset went.
func TestMergeAssetsWithUpperCaseIDsStillAnswersMergedInto(t *testing.T) {
	runtime := newRuntime(t)
	server := testServer(t, runtime)
	cookie, csrf := authenticateInitialAdmin(t, server, runtime)
	now := time.Now().UTC()
	primaryID := insertSoftwareTestAsset(t, server, "hint-primary", "hint-primary",
		"host", `{}`, 1, now)
	secondaryID := insertSoftwareTestAsset(t, server, "hint-secondary",
		"hint-secondary", "host", `{}`, 1, now.Add(-time.Minute))

	status, code := mergeAssetsResponse(t, server, cookie, csrf,
		strings.ToUpper(primaryID), strings.ToUpper(secondaryID))
	if status != http.StatusOK {
		t.Fatalf("merge with upper-case ids = %d %q, want 200", status, code)
	}
	merged, err := mcpAssetGetReplyFor(t, server, secondaryID)
	if err != nil {
		t.Fatalf("asset_get on the merged asset returned an error: %v", err)
	}
	if merged.MergedInto != primaryID {
		t.Fatalf("merged_into = %q, want the primary %q", merged.MergedInto, primaryID)
	}
}

