func queryInt(
	request *http.Request, name string, fallback int, minimum int, maximum int,
) int {
	value, err := strconv.Atoi(request.URL.Query().Get(name))
	if err != nil {
		return fallback
	}
	if value < minimum {
		return minimum
	}
	if value > maximum {
		return maximum
	}
	return value
}

func boolInt(value bool) int {
	if value {
		return 1
	}
	return 0
}

